paragraph.math:
$$\begin{array}{lll}
  {s(x)} & = & {(f + g)(x) = f(x) + g(x) = \sqrt{x + 1} + 2x + 1} \\
  {d(x)} & = & {(f - g)(x) = f(x) - g(x) = \sqrt{x + 1} - (2x + 1) = \sqrt{x + 1} - 2x - 1} \\
  {p(x)} & = & {\left( \mathit{fg} \right)(x) = f(x)g(x) = \sqrt{x + 1}(2x + 1) = (2x + 1)\sqrt{x + 1}}
  \end{array}$$

$$\begin{array}{l}
  {(f \circ g){(x) = f(g(x)) = \left( g(x) \right)^{2} - 1 = \left( \sqrt{x} + 1 \right)^{2} - 1}} \\
  {\phantom{(f \circ g)(x)} = x + 2\sqrt{x} + 1 - 1 = x + 2\sqrt{x}}
  \end{array}$$

$$\begin{array}{lll}
  {s(x)} & = & {f(x) + g(x) = \sqrt{x} + 1 + \frac{x}{1 + x}} \\
  {d(x)} & = & {f(x) - g(x) = \sqrt{x} + 1 - \frac{x}{1 + x}} \\
  {p(x)} & = & {f(x)g(x) = (\sqrt{x} + 1) \cdot \frac{x}{1 + x} = \frac{x(\sqrt{x} + 1)}{1 + x}} \\
  {q(x)} & = & {\frac{f(x)}{g(x)} = \frac{\sqrt{x} + 1}{\frac{x}{1 + x}} = \frac{(\sqrt{x} + 1)(1 + x)}{x}}
  \end{array}$$

$$\begin{array}{l}
  {R = (200 + x)(300 - x)} \\
  {\phantom{R} = - x^{2} + 100x + 60,000}
  \end{array}\qquad\begin{array}{l}
  {\text{Number of passengers~} \times} \\
  \text{the fare per passenger}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\text{Distance covered}}{\text{Time elapsed}} = \frac{f(4) - f(2)}{4 - 2}} \\
  {\phantom{\frac{\text{Distance covered}}{\text{Time elapsed}}} = \frac{4{(4^{2})} - 4{(2^{2})}}{2}} \\
  {\phantom{\frac{\text{Distance covered}}{\text{Time elapsed}}} = \frac{64 - 16}{2} = 24}
  \end{array}$$

item.paragraph:
            $$f(x) = \{\begin{aligned}
{- 1} & {\quad{if}x < 0} \\
1 & {\quad{if}x \geq 0}
\end{aligned}$$ ; $$x = 0$$

paragraph.math:
$$\begin{array}{l}
  {\frac{\sqrt{1 + h} - 1}{h} = \frac{({\sqrt{1 + h} - 1})({\sqrt{1 + h} + 1})}{h{({\sqrt{1 + h} + 1})}}\qquad{({\sqrt{a} - \sqrt{b}})({\sqrt{a} + \sqrt{b}}) = a - b}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1 + h - 1}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{h}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1}{\sqrt{1 + h} + 1}}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3} = \lim\limits_{x\rightarrow - 1}\frac{\left( {x + 1} \right)\left( {x - 2} \right)}{\left( {x + 1} \right)\left( {2x - 3} \right)}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \lim\limits_{x\rightarrow - 1}\frac{x - 2}{2x - 3}\qquad{\text{Cancel the common factors}.}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \frac{- 1 - 2}{2\left( {- 1} \right) - 3}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \frac{3}{5}}
  \end{array}$$

$$\begin{array}{l}
  {f\left( {x + h} \right) - f(x) = x^{2} + 2xh + h^{2} - 4x - 4h - {({x^{2} - 4x})}} \\
  {\phantom{f\left( {x + h} \right) - f(x)} = 2\mathit{xh} + h^{2} - 4h = h\left( {2x + h - 4} \right)}
  \end{array}$$

$$\begin{array}{l}
  {\frac{f\left( {t + h} \right) - f(t)}{h} = \frac{2\left( {t + h} \right)^{2} - 2t^{2}}{h}} \\
  {\phantom{\frac{f\left( {t + h} \right) - f(t)}{h}} = \frac{2t^{2} + 4th + 2h^{2} - 2t^{2}}{h}} \\
  {\phantom{\frac{f\left( {t + h} \right) - f(t)}{h}} = 4t + 2h}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{h\rightarrow 0}\frac{f\left( {t + h} \right) - f(t)}{h} = \lim\limits_{h\rightarrow 0}\left( {4t + 2h} \right)\qquad{\text{Use the results from part~}(a).}} \\
  {\phantom{\lim\limits_{h\rightarrow 0}\frac{f\left( {t + h} \right) - f(t)}{h}} = 4t}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{h\rightarrow 0}\frac{f\left( {x + h} \right) - f(x)}{h} = \lim\limits_{h\rightarrow 0}\left( {- 2x - h} \right)\qquad{\text{Use the results from part~}(a).}} \\
  {\phantom{\lim\limits_{h\rightarrow 0}\frac{f\left( {x + h} \right) - f(x)}{h}} = - 2x}
  \end{array}$$
